window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ae3514b4d53da9f5"]={"versions": [{"id": "FIG-ae3514b4d53da9f5", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Sequentielles Ablauf- bzw. Zeitstrahldiagramm (Ausführungsreihenfolge) innerhalb des AUTOSAR Classic Platform LIN Interfaces ([<code>LinIf</code>](file:///AUTOSAR_SWS_LIN_Interface)). Das Diagramm visualisiert die chronologische Abarbeitung von LIN-Schedule-Tabellen auf einem LIN-Kanal.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind aufeinanderfolgende Schedule-Tabellen-Slots bzw. Tabelleneinträge als Zellen einer linearen Abfolge:</p>\n<ul class=\"fig-list\">\n<li><code>ReadById</code>: Diagnostische bzw. identifizierende LIN-Schedule-Tabelle (zweimal in Folge ausgeführt).</li>\n<li><code>CheckSensors</code>: Anwendungsspezifische Schedule-Tabelle zur Sensorabfrage.</li>\n<li><code>Null-schedule</code>: Standard- bzw. Ruhezustands-Schedule-Tabelle (Null-Schedule) zur Deaktivierung der periodischen Kommunikation.</li>\n<li><code>...</code>: Fortsetzung der Schedule-Ausführungssequenz.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Abfolge zeigt die Ausführung von Tabellenumschaltungen durch den LIN Interface Master:</p>\n<ol class=\"fig-list\">\n<li>Initiale Ausführung der Tabelle <code>ReadById</code>.</li>\n<li>Erneute Ausführung der Tabelle <code>ReadById</code> (z. B. nach erneutem Request).</li>\n<li>Wechsel und Abarbeitung der Schedule-Tabelle <code>CheckSensors</code>.</li>\n<li>Umschaltung auf die <code>Null-schedule</code> zur Beendigung oder Pausierung der zyklischen LIN-Rahmenübertragung.</li>\n<li>Nachfolgende Fortsetzung (<code>...</code>) gemäß weiterer externer oder interner Umschaltanforderungen.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild illustriert beispielhaft das Umschaltverhalten des LIN-Interface-Schedulers (<code>LinIf_ScheduleRequest</code>). Ein Wechsel der Schedule-Tabelle erfolgt deterministisch an den definierten Tabellen- oder Slot-Grenzen. Die Aktivierung der <code>Null-schedule</code> stoppt die Übertragung regulärer Botschaftsrahmen auf dem LIN-Bus, hält den Bus jedoch synchronisiert bzw. betriebsbereit.</p>"}, {"id": "FIG-a34b90a8c0b52e76", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Sequentielles Ablauf- bzw. Zeitstrahldiagramm (Ausführungsreihenfolge) innerhalb des AUTOSAR Classic Platform LIN Interfaces ([<code>LinIf</code>](file:///AUTOSAR_SWS_LIN_Interface)). Das Diagramm visualisiert die chronologische Abarbeitung von LIN-Schedule-Tabellen auf einem LIN-Kanal.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind aufeinanderfolgende Schedule-Tabellen-Slots bzw. Tabelleneinträge als Zellen einer linearen Abfolge:</p>\n<ul class=\"fig-list\">\n<li><code>ReadById</code>: Diagnostische bzw. identifizierende LIN-Schedule-Tabelle (zweimal in Folge ausgeführt).</li>\n<li><code>CheckSensors</code>: Anwendungsspezifische Schedule-Tabelle zur Sensorabfrage.</li>\n<li><code>Null-schedule</code>: Standard- bzw. Ruhezustands-Schedule-Tabelle (Null-Schedule) zur Deaktivierung der periodischen Kommunikation.</li>\n<li><code>...</code>: Fortsetzung der Schedule-Ausführungssequenz.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Abfolge zeigt die Ausführung von Tabellenumschaltungen durch den LIN Interface Master:</p>\n<ol class=\"fig-list\">\n<li>Initiale Ausführung der Tabelle <code>ReadById</code>.</li>\n<li>Erneute Ausführung der Tabelle <code>ReadById</code> (z. B. nach erneutem Request).</li>\n<li>Wechsel und Abarbeitung der Schedule-Tabelle <code>CheckSensors</code>.</li>\n<li>Umschaltung auf die <code>Null-schedule</code> zur Beendigung oder Pausierung der zyklischen LIN-Rahmenübertragung.</li>\n<li>Nachfolgende Fortsetzung (<code>...</code>) gemäß weiterer externer oder interner Umschaltanforderungen.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild illustriert beispielhaft das Umschaltverhalten des LIN-Interface-Schedulers (<code>LinIf_ScheduleRequest</code>). Ein Wechsel der Schedule-Tabelle erfolgt deterministisch an den definierten Tabellen- oder Slot-Grenzen. Die Aktivierung der <code>Null-schedule</code> stoppt die Übertragung regulärer Botschaftsrahmen auf dem LIN-Bus, hält den Bus jedoch synchronisiert bzw. betriebsbereit.</p>"}], "trans": [{"from": "FIG-ae3514b4d53da9f5", "to": "FIG-a34b90a8c0b52e76", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
